/* Interactive skill-tree board for the wiki.
 *
 * Reads window.NARUTO_SKILL_TREE (generated by tools/build_docs_skills.py) and draws the same
 * two-level board the game shows: sections on top, branches below, one branch per canvas. No
 * purchases and no editing - hovering shows a node, clicking pins its card on the right, and the
 * "Вся карта" button lays every branch out at once. The markup lives in docs/skills.html inside
 * the SKILLS markers.
 */
(function () {
  'use strict';

  var data = window.NARUTO_SKILL_TREE;
  var app = document.querySelector('[data-tree-app]');
  if (!data || !app) return;

  var GRID_X = 118, GRID_Y = 86, NODE = 30, HALF = NODE / 2;
  var MIN_ZOOM = 0.12, MAX_ZOOM = 1.7;
  var HIGHLIGHT = '#ffd37f';

  var nodes = data.nodes;
  var branches = data.branches;
  var branchList = data.branchList;
  var sections = data.sections;
  var sectionList = data.sectionList;

  var byPath = new Map();
  nodes.forEach(function (n, i) { byPath.set(n.path, i); });
  nodes.forEach(function (n) {
    n.req = (n.requires || []).map(function (p) { return byPath.has(p) ? byPath.get(p) : -1; })
      .filter(function (i) { return i >= 0; });
    n.byBranch = n.byBranch || null;
  });

  var canvas = document.getElementById('tree-canvas');
  var stage = canvas.parentNode;
  var tip = document.getElementById('tree-tip');
  var info = document.getElementById('tree-info');
  var resultsBox = document.getElementById('tree-results');
  var search = document.getElementById('tree-search');
  var sectionsRow = document.getElementById('tree-sections');
  var branchesRow = document.getElementById('tree-branches');
  var ctx = canvas.getContext('2d');

  var board = branchList.find(function (name) {
    return nodes.some(function (n) { return n.branch === name; });
  }) || branchList[0];
  var activeSection = board && branches[board] ? branches[board].section : sectionList[0];
  var mode = 'board';
  var views = new Map();
  var overviewView = null;
  var panX = 0, panY = 0, zoom = 0.7;
  var hovered = -1, selected = -1;
  var layout = { pos: new Map(), visible: new Set(), frames: [] };
  var pointers = new Map();
  var drag = null;
  var pinch = null;
  var moved = false;

  function escapeHtml(text) {
    return String(text == null ? '' : text)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }
  function branchLabel(name) { return branches[name] ? branches[name].label : name; }
  function branchColour(name) { return branches[name] ? branches[name].colour : '#888888'; }
  function width() { return canvas.clientWidth || stage.clientWidth || 800; }
  function height() { return canvas.clientHeight || stage.clientHeight || 460; }
  function nodeX(n) { var p = layout.pos.get(n.path); return p ? p.x : n.x * GRID_X; }
  function nodeY(n) { var p = layout.pos.get(n.path); return p ? p.y : n.y * GRID_Y; }
  function toTree(px, py) {
    return [(px - (width() / 2 + panX)) / zoom, (py - (height() / 2 + panY)) / zoom];
  }
  function toScreen(wx, wy) {
    return [width() / 2 + panX + wx * zoom, height() / 2 + panY + wy * zoom];
  }
  function nodeAt(px, py) {
    var t = toTree(px, py);
    var tol = Math.max(HALF, 9 / zoom);
    for (var i = 0; i < nodes.length; i++) {
      if (!layout.visible.has(nodes[i].path)) continue;
      if (Math.abs(t[0] - nodeX(nodes[i])) <= tol && Math.abs(t[1] - nodeY(nodes[i])) <= tol) {
        return i;
      }
    }
    return -1;
  }
  function route(start) {
    var lit = new Set();
    if (start < 0) return lit;
    var stack = [start];
    while (stack.length) {
      var i = stack.pop();
      if (lit.has(i)) continue;
      lit.add(i);
      nodes[i].req.forEach(function (j) { stack.push(j); });
    }
    return lit;
  }

  // --- layout ----------------------------------------------------------------------------------

  function recomputeLayout() {
    layout = { pos: new Map(), visible: new Set(), frames: [] };
    if (mode === 'board') {
      nodes.forEach(function (n) {
        if (n.branch !== board) return;
        layout.visible.add(n.path);
        layout.pos.set(n.path, { x: n.x * GRID_X, y: n.y * GRID_Y });
      });
      return;
    }

    var PAD = 34, TITLE = 30, GAP = 46;
    var boards = branchList.map(function (name) {
      var list = nodes.filter(function (n) { return n.branch === name; });
      var minX = 0, maxX = 0, minY = 0, maxY = 0;
      list.forEach(function (n) {
        minX = Math.min(minX, n.x); maxX = Math.max(maxX, n.x);
        minY = Math.min(minY, n.y); maxY = Math.max(maxY, n.y);
      });
      var w = list.length ? (maxX - minX) * GRID_X + PAD * 2 : 300;
      // Keep the branch title readable even when its board is only one node wide.
      w = Math.max(w, branchLabel(name).length * 7.5 + 62);
      var h = list.length ? (maxY - minY) * GRID_Y + PAD * 2 + TITLE : 90;
      return { name: name, list: list, minX: minX, minY: minY, w: w, h: h };
    });
    var area = boards.reduce(function (sum, b) { return sum + (b.w + GAP) * (b.h + GAP); }, 0);
    var aspect = Math.max(0.55, width() / Math.max(1, height()));
    var cap = Math.max(1500, Math.sqrt(area * aspect / 0.72));

    var cursorX = 0, cursorY = 0, rowHeight = 0;
    boards.forEach(function (b) {
      if (cursorX > 0 && cursorX + b.w > cap) {
        cursorX = 0; cursorY += rowHeight + GAP; rowHeight = 0;
      }
      var frame = { branch: b.name, x: cursorX, y: cursorY, w: b.w, h: b.h };
      var ox = cursorX + PAD - b.minX * GRID_X;
      var oy = cursorY + TITLE + PAD - b.minY * GRID_Y;
      b.list.forEach(function (n) {
        layout.visible.add(n.path);
        layout.pos.set(n.path, { x: ox + n.x * GRID_X, y: oy + n.y * GRID_Y });
      });
      layout.frames.push(frame);
      cursorX += b.w + GAP;
      rowHeight = Math.max(rowHeight, b.h);
    });
  }

  function saveView() {
    if (mode === 'overview') overviewView = { panX: panX, panY: panY, zoom: zoom };
    else if (board) views.set(board, { panX: panX, panY: panY, zoom: zoom });
  }
  function fit() {
    var x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    layout.visible.forEach(function (path) {
      var n = nodes[byPath.get(path)];
      var x = nodeX(n), y = nodeY(n);
      x0 = Math.min(x0, x); y0 = Math.min(y0, y);
      x1 = Math.max(x1, x); y1 = Math.max(y1, y);
    });
    var availW = Math.max(160, width() - 24);
    var availH = Math.max(160, height() - 24);
    if (!isFinite(x0)) {
      zoom = 0.8; panX = 0; panY = 0; return;
    }
    var pad = mode === 'overview' ? 22 : 34;
    zoom = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, Math.min(
      availW / (x1 - x0 + pad * 2), availH / (y1 - y0 + pad * 2))));
    panX = -(x0 + x1) / 2 * zoom;
    panY = -(y0 + y1) / 2 * zoom;
  }
  function restoreView() {
    var view = mode === 'overview' ? overviewView : (board ? views.get(board) : null);
    if (view) { panX = view.panX; panY = view.panY; zoom = view.zoom; }
    else fit();
  }

  // --- drawing ---------------------------------------------------------------------------------

  function drawLine(x1, y1, x2, y2, lineWidth, colour) {
    var steps = Math.max(Math.abs(x2 - x1), Math.abs(y2 - y1));
    var cells = Math.max(1, Math.ceil(steps / lineWidth));
    ctx.fillStyle = colour;
    for (var i = 0; i <= cells; i++) {
      var t = i / cells;
      ctx.fillRect(Math.round(x1 + (x2 - x1) * t) - lineWidth / 2,
        Math.round(y1 + (y2 - y1) * t) - lineWidth / 2, lineWidth, lineWidth);
    }
  }
  function clipText(text, room) {
    if (ctx.measureText(text).width <= room) return text;
    var out = text;
    while (out.length > 1 && ctx.measureText(out + '…').width > room) out = out.slice(0, -1);
    return out + '…';
  }

  function draw() {
    if (!canvas) return;
    var w = width(), h = height();
    var dpr = window.devicePixelRatio || 1;
    if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    var bg = ctx.createLinearGradient(0, 0, 0, h);
    bg.addColorStop(0, '#0d1015');
    bg.addColorStop(1, '#12161d');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, w, h);

    // A faint dot grid keeps the board readable at any zoom.
    if (mode === 'board') {
      ctx.fillStyle = 'rgba(255,255,255,0.055)';
      var stepX = GRID_X * zoom, stepY = GRID_Y * zoom;
      if (stepX > 14 && stepY > 14) {
        var ox = (w / 2 + panX) % stepX, oy = (h / 2 + panY) % stepY;
        for (var gx = ox; gx < w; gx += stepX) {
          for (var gy = oy; gy < h; gy += stepY) ctx.fillRect(gx, gy, 1, 1);
        }
      }
    }

    ctx.save();
    ctx.translate(w / 2 + panX, h / 2 + panY);
    ctx.scale(zoom, zoom);
    var cell = Math.max(1, Math.ceil(1 / zoom));
    var lit = route(hovered >= 0 ? hovered : selected);

    // Edges: twice, so the highlighted path lands on top of the dim ones.
    for (var pass = 0; pass < 2; pass++) {
      nodes.forEach(function (n, i) {
        if (!layout.visible.has(n.path)) return;
        var onRoute = lit.size > 1 && lit.has(i);
        if ((pass === 1) !== onRoute) return;
        n.req.forEach(function (j) {
          var other = nodes[j];
          if (!other || !layout.visible.has(other.path)) return;
          drawLine(nodeX(other), nodeY(other), nodeX(n), nodeY(n),
            onRoute ? cell + 1 : cell,
            onRoute ? HIGHLIGHT : 'rgba(180,190,205,0.16)');
        });
      });
    }

    // Nodes.
    nodes.forEach(function (n, i) {
      if (!layout.visible.has(n.path)) return;
      var cx = nodeX(n), cy = nodeY(n);
      var isHover = hovered === i, isSel = selected === i;
      var colour = branchColour(n.branch);
      ctx.fillStyle = isSel ? '#ffffff' : (isHover ? '#ffffff' : colour);
      ctx.fillRect(cx - HALF, cy - HALF, NODE, NODE);
      ctx.fillStyle = '#0f1218';
      ctx.font = '700 13px ui-monospace, Consolas, monospace';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(n.cost >= 1000 ? (n.cost / 1000) + 'k' : String(n.cost), cx, cy + 0.5);

      if (mode === 'board' && (isHover || isSel || zoom >= 0.6)) {
        ctx.font = '11px system-ui, Segoe UI, sans-serif';
        ctx.fillStyle = isHover || isSel ? '#ffffff' : 'rgba(220,228,240,0.82)';
        ctx.fillText(clipText(n.name, 112), cx, cy + HALF + 12);
      }
    });
    ctx.restore();

    if (mode === 'overview') {
      layout.frames.forEach(function (fr) {
        var s = toScreen(fr.x, fr.y);
        var fw = fr.w * zoom, fh = fr.h * zoom;
        var active = fr.branch === board;
        ctx.fillStyle = active ? 'rgba(255,255,255,0.045)' : 'rgba(255,255,255,0.02)';
        ctx.fillRect(s[0], s[1], fw, fh);
        ctx.strokeStyle = active ? branchColour(fr.branch) : 'rgba(180,190,205,0.22)';
        ctx.lineWidth = active ? 1.5 : 1;
        ctx.strokeRect(Math.round(s[0]) + 0.5, Math.round(s[1]) + 0.5, Math.round(fw), Math.round(fh));
        var bar = Math.min(fh, 24);
        ctx.fillStyle = 'rgba(0,0,0,0.35)';
        ctx.fillRect(s[0], s[1], fw, bar);
        var count = nodes.filter(function (n) { return n.branch === fr.branch; }).length;
        ctx.fillStyle = '#eef3ff';
        ctx.font = '600 11px system-ui, Segoe UI, sans-serif';
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText(clipText(branchLabel(fr.branch), Math.max(20, fw - 44)), s[0] + 7, s[1] + bar / 2);
        ctx.fillStyle = 'rgba(200,212,228,0.7)';
        ctx.textAlign = 'right';
        ctx.fillText(String(count), s[0] + fw - 7, s[1] + bar / 2);
      });
    }

  }

  // --- tabs and side panel ---------------------------------------------------------------------

  function tabButton(label, count, active, onClick) {
    var button = document.createElement('button');
    button.type = 'button';
    button.className = 'tree__tab' + (active ? ' on' : '');
    button.setAttribute('role', 'tab');
    button.setAttribute('aria-selected', active ? 'true' : 'false');
    button.innerHTML = escapeHtml(label) + (count == null ? '' :
      ' <span class="tree__count">' + count + '</span>');
    button.addEventListener('click', onClick);
    return button;
  }

  function buildTabs() {
    sectionsRow.textContent = '';
    sectionList.forEach(function (name) {
      var total = nodes.filter(function (n) { return branches[n.branch].section === name; }).length;
      sectionsRow.appendChild(tabButton(sections[name].label, total, mode === 'board' && activeSection === name, function () {
        switchSection(name);
      }));
    });

    branchesRow.textContent = '';
    branchList.forEach(function (name) {
      if (branches[name].section !== activeSection) return;
      var count = nodes.filter(function (n) { return n.branch === name; }).length;
      branchesRow.appendChild(tabButton(branchLabel(name), count,
        mode === 'board' && board === name, function () { switchBoard(name); }));
    });
    var overview = tabButton('Вся карта', nodes.length, mode === 'overview', showOverview);
    overview.classList.add('tree__tab--overview');
    branchesRow.appendChild(overview);
  }

  function branchStats(name) {
    var list = nodes.filter(function (n) { return n.branch === name; });
    var cost = list.reduce(function (sum, n) { return sum + n.cost; }, 0);
    var unlocks = list.filter(function (n) { return n.kind === 'unlock'; }).length;
    return { count: list.length, cost: cost, unlocks: unlocks, passives: list.length - unlocks };
  }

  function showInfo() {
    if (selected < 0) {
      var name = mode === 'overview' ? null : board;
      if (!name) {
        info.innerHTML = '<h3 class="tree__info-title">Вся карта</h3>' +
          '<p class="tree__muted">' + branchList.length + ' веток, ' + nodes.length +
          ' узлов. Нажмите на ветку в списке сверху, чтобы рассмотреть её отдельно.</p>';
        return;
      }
      var stats = branchStats(name);
      info.innerHTML =
        '<div class="tree__info-head"><span class="tree__swatch" style="background:' +
        branchColour(name) + '"></span><h3 class="tree__info-title">' + escapeHtml(branchLabel(name)) +
        '</h3></div>' +
        '<dl class="tree__facts">' +
        '<div><dt>Узлов</dt><dd>' + stats.count + '</dd></div>' +
        '<div><dt>Стоимость</dt><dd>' + stats.cost + ' очк.</dd></div>' +
        '<div><dt>Открытий</dt><dd>' + stats.unlocks + '</dd></div>' +
        '<div><dt>Пассивок</dt><dd>' + stats.passives + '</dd></div>' +
        '</dl><p class="tree__muted">Нажмите на узел, чтобы увидеть цену, бонус и цепочку ' +
        'предков. Узел без стрелок — центр ветки, с него начинается всё остальное.</p>';
      return;
    }

    var n = nodes[selected];
    var chips = n.req.length ? n.req.map(function (j) {
      var other = nodes[j];
      return '<button type="button" class="tree__chip" data-tree-goto="' + escapeHtml(other.path) +
        '">' + escapeHtml(other.name) + '</button>';
    }).join(' ') : '<span class="tree__muted">— это центр ветки</span>';

    info.innerHTML =
      '<div class="tree__info-head"><span class="tree__swatch" style="background:' +
      branchColour(n.branch) + '"></span><h3 class="tree__info-title">' + escapeHtml(n.name) +
      '</h3></div>' +
      '<p class="tree__where">' + escapeHtml(branchLabel(n.branch)) + ' · ' +
      escapeHtml(n.path) + '</p>' +
      '<dl class="tree__facts">' +
      '<div><dt>Цена</dt><dd>' + n.cost + ' очк.</dd></div>' +
      '<div><dt>' + (n.kind === 'unlock' ? 'Открывает' : 'Даёт') + '</dt><dd>' +
      escapeHtml(n.gain) + '</dd></div>' +
      '</dl>' +
      '<h4 class="tree__info-sub">Нужно сначала</h4>' +
      '<div class="tree__chips">' + chips + '</div>' +
      (n.desc ? '<p class="tree__desc">' + escapeHtml(n.desc) + '</p>' : '') +
      (n.nameEn && n.nameEn !== n.path && n.nameEn !== n.name
        ? '<p class="tree__muted">In game: ' + escapeHtml(n.nameEn) + '</p>' : '');

    info.querySelectorAll('[data-tree-goto]').forEach(function (button) {
      button.addEventListener('click', function () {
        var i = byPath.get(button.getAttribute('data-tree-goto'));
        if (i != null) selectNode(i, true);
      });
    });
  }

  function selectNode(i, centre) {
    selected = i;
    if (i >= 0) {
      var n = nodes[i];
      if (mode !== 'board' || n.branch !== board) {
        saveView();
        mode = 'board';
        board = n.branch;
        activeSection = branches[board].section;
        recomputeLayout();
        buildTabs();
        fit();
      }
      if (centre !== false) {
        panX = -nodeX(n) * zoom;
        panY = -nodeY(n) * zoom;
      }
    }
    showInfo();
    draw();
  }

  function switchBoard(name) {
    if (!branches[name]) return;
    saveView();
    mode = 'board';
    board = name;
    activeSection = branches[name].section;
    if (selected >= 0 && nodes[selected].branch !== board) selected = -1;
    recomputeLayout();
    buildTabs();
    showInfo();
    restoreView();
    draw();
  }
  function switchSection(name) {
    activeSection = name;
    var first = branchList.find(function (b) { return branches[b].section === name; });
    if (first) switchBoard(first);
    else { buildTabs(); draw(); }
  }
  function showOverview() {
    saveView();
    mode = 'overview';
    recomputeLayout();
    buildTabs();
    showInfo();
    restoreView();
    draw();
  }

  // --- pointer and wheel -----------------------------------------------------------------------

  function stagePoint(event) {
    var rect = stage.getBoundingClientRect();
    return [event.clientX - rect.left, event.clientY - rect.top];
  }
  function zoomAt(px, py, factor) {
    var before = toTree(px, py);
    zoom = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, zoom * factor));
    panX = px - width() / 2 - before[0] * zoom;
    panY = py - height() / 2 - before[1] * zoom;
  }
  function showTip(i, px, py) {
    if (i < 0) { tip.hidden = true; return; }
    var n = nodes[i];
    tip.innerHTML = '<strong>' + escapeHtml(n.name) + '</strong>' +
      '<span class="tree__tip-where">' + escapeHtml(branchLabel(n.branch)) + '</span>' +
      '<span class="tree__tip-gain">' + escapeHtml(n.gain) + '</span>' +
      '<span class="tree__tip-cost">' + n.cost + ' очк.</span>';
    tip.hidden = false;
    var tw = tip.offsetWidth || 200, th = tip.offsetHeight || 60;
    var left = Math.min(Math.max(8, px + 14), width() - tw - 8);
    var top = Math.min(Math.max(8, py + 14), height() - th - 8);
    tip.style.left = left + 'px';
    tip.style.top = top + 'px';
  }

  canvas.addEventListener('pointerdown', function (event) {
    canvas.setPointerCapture(event.pointerId);
    var p = stagePoint(event);
    pointers.set(event.pointerId, p);
    moved = false;
    if (pointers.size === 2) {
      var list = Array.from(pointers.values());
      pinch = {
        distance: Math.hypot(list[0][0] - list[1][0], list[0][1] - list[1][1]),
        zoom: zoom
      };
      drag = null;
      return;
    }
    drag = { x: p[0], y: p[1], panX: panX, panY: panY, id: event.pointerId };
  });

  canvas.addEventListener('pointermove', function (event) {
    var p = stagePoint(event);
    if (pointers.has(event.pointerId)) pointers.set(event.pointerId, p);

    if (pinch && pointers.size === 2) {
      var list = Array.from(pointers.values());
      var distance = Math.hypot(list[0][0] - list[1][0], list[0][1] - list[1][1]);
      var cx = (list[0][0] + list[1][0]) / 2, cy = (list[0][1] + list[1][1]) / 2;
      zoomAt(cx, cy, (pinch.zoom * distance / Math.max(1, pinch.distance)) / zoom);
      draw();
      return;
    }

    if (drag) {
      var dx = p[0] - drag.x, dy = p[1] - drag.y;
      if (Math.abs(dx) + Math.abs(dy) > 3) moved = true;
      if (moved) {
        panX = drag.panX + dx;
        panY = drag.panY + dy;
        tip.hidden = true;
        draw();
        return;
      }
    }

    var i = nodeAt(p[0], p[1]);
    if (i !== hovered) {
      hovered = i;
      canvas.style.cursor = i >= 0 ? 'pointer' : (moved ? 'grabbing' : 'grab');
      draw();
    }
    showTip(i, p[0], p[1]);
  });

  function endPointer(event) {
    pointers.delete(event.pointerId);
    if (pointers.size < 2) pinch = null;
    if (drag && drag.id === event.pointerId) {
      if (!moved) {
        var p = stagePoint(event);
        var i = nodeAt(p[0], p[1]);
        if (i >= 0) selectNode(i, false);
      }
      drag = null;
    }
  }
  canvas.addEventListener('pointerup', endPointer);
  canvas.addEventListener('pointercancel', endPointer);
  canvas.addEventListener('pointerleave', function () {
    if (!pointers.size) { hovered = -1; tip.hidden = true; draw(); }
  });

  canvas.addEventListener('wheel', function (event) {
    event.preventDefault();
    var p = stagePoint(event);
    var factor = Math.exp(-event.deltaY * 0.0016);
    zoomAt(p[0], p[1], factor);
    draw();
  }, { passive: false });

  // --- toolbar and search ----------------------------------------------------------------------

  document.querySelectorAll('[data-tree-zoom]').forEach(function (button) {
    button.addEventListener('click', function () {
      var action = button.getAttribute('data-tree-zoom');
      if (action === 'fit') fit();
      else zoomAt(width() / 2, height() / 2, action === 'in' ? 1.25 : 0.8);
      draw();
    });
  });

  function toggleWide() {
    app.classList.toggle('is-wide');
    document.documentElement.style.overflow = app.classList.contains('is-wide') ? 'hidden' : '';
    fit();
    draw();
    window.setTimeout(function () { fit(); draw(); }, 30);
    var button = document.querySelector('[data-tree-wide]');
    if (button) {
      button.classList.toggle('on', app.classList.contains('is-wide'));
      button.setAttribute('title', app.classList.contains('is-wide')
        ? 'Свернуть' : 'Развернуть на весь экран');
    }
  }
  var wideButton = document.querySelector('[data-tree-wide]');
  if (wideButton) wideButton.addEventListener('click', toggleWide);
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape' && app.classList.contains('is-wide')) toggleWide();
  });

  function hideResults() { resultsBox.hidden = true; resultsBox.textContent = ''; }

  search.addEventListener('input', function () {
    var query = search.value.trim().toLowerCase();
    if (query.length < 2) { hideResults(); return; }
    var hits = [];
    nodes.forEach(function (n, i) {
      var haystack = (n.name + ' ' + n.nameEn + ' ' + n.path + ' ' + n.gain + ' ' +
        branchLabel(n.branch)).toLowerCase();
      var at = haystack.indexOf(query);
      if (at >= 0) hits.push({ i: i, n: n, score: at + haystack.length / 1000 });
    });
    hits.sort(function (a, b) { return a.score - b.score; });
    hits = hits.slice(0, 12);
    resultsBox.textContent = '';
    if (!hits.length) {
      resultsBox.innerHTML = '<div class="tree__none">Ничего не найдено</div>';
      resultsBox.hidden = false;
      return;
    }
    hits.forEach(function (hit) {
      var button = document.createElement('button');
      button.type = 'button';
      button.className = 'tree__hit';
      button.innerHTML = '<span>' + escapeHtml(hit.n.name) + '</span>' +
        '<span class="tree__hit-where">' + escapeHtml(branchLabel(hit.n.branch)) +
        ' · ' + hit.n.cost + ' очк.</span>';
      button.addEventListener('click', function () {
        hideResults();
        selectNode(hit.i, true);
      });
      resultsBox.appendChild(button);
    });
    resultsBox.hidden = false;
  });

  search.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') { search.value = ''; hideResults(); search.blur(); }
    if (event.key === 'Enter') {
      var first = resultsBox.querySelector('.tree__hit');
      if (first) first.click();
    }
  });
  document.addEventListener('click', function (event) {
    if (!resultsBox.hidden && !resultsBox.contains(event.target) && event.target !== search) {
      hideResults();
    }
  });

  // --- boot ------------------------------------------------------------------------------------

  recomputeLayout();
  buildTabs();
  showInfo();
  fit();
  draw();

  if (window.ResizeObserver) {
    new ResizeObserver(function () { draw(); }).observe(stage);
  } else {
    window.addEventListener('resize', draw);
  }

  window.NarutoSkillTree = {
    open: function (path) {
      var i = byPath.get(path);
      if (i != null) selectNode(i, true);
    }
  };
})();
